   "subs": [
    {
     "t0": 0.23,
     "t1": 6.37,
     "text": "Y debajo de cada emoción hay un miedo. Los medimos por tallas, como los pañales:"
    },
    {
     "t0": 6.39,
     "t1": 11.04,
     "text": "de la XS, que incomoda un rato, a la XXL, que te encierra en la casa."
    },
    {
     "t0": 11.66,
     "t1": 16.54,
     "text": "XS: que se arruine el plan. Una fuga no solo daña la ropa, daña la salida."
    },
    {
     "t0": 16.61,
     "t1": 22.11,
     "text": "S: ser el que ensucia lo ajeno. Lo que toca el popó queda marcado, aunque lo laves."
    },
    {
     "t0": 22.13,
     "t1": 23.48,
     "text": "M: quedar en ridículo,"
    },
    {
     "t0": 23.5,
     "t1": 28.27,
     "text": "porque un escape en público acaba con la imagen de papá que lo tiene todo bajo control."
    },
    {
     "t0": 28.38,
     "t1": 31.89,
     "text": "L: que me juzguen como mal papá. Y los jueces están en casa:"
    },
    {
     "t0": 31.91,
     "t1": 36.44,
     "text": "6 de cada 10 mamás han sido criticadas, sobre todo por la familia."
    },
    {
     "t0": 36.46,
     "t1": 38.89,
     "text": "XL: perder lo que tanto me costó."
    },
    {
     "t0": 38.91,
     "t1": 44.66,
     "text": "Perder duele casi el doble que ganar, y por eso la campaña arriesgó medio millón de dólares."
    },
    {
     "t0": 44.89,
     "t1": 50.67,
     "text": "Y la XXL: perder la libertad. Si cada salida es un riesgo, uno termina encerrado."
    },
    {
     "t0": 50.69,
     "t1": 53.92,
     "text": "Ese es el miedo más grande, el que Huggies vino a resolver."
    }
   ]
